import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { cause8Schema, type Cause8 } from "./cause8.js";

export type RequestCancelExternalWorkflowExecutionFailedEventAttributes = {
  /** The workflowId of the external workflow to which the cancel request was to be delivered. */
  workflowId: string;
  /** The runId of the external workflow execution. */
  runId?: string;
  /**
   * The cause of the failure. This information is generated by the system and can be useful for
   * diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it
   * lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage
   * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
   */
  cause: Cause8;
  /**
   * The ID of the RequestCancelExternalWorkflowExecutionInitiated event corresponding to the
   * RequestCancelExternalWorkflowExecution decision to cancel this external workflow execution.
   * This information can be useful for diagnosing problems by tracing back the chain of events
   * leading up to this event.
   */
  initiatedEventId: number;
  /**
   * The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in
   * the RequestCancelExternalWorkflowExecution decision for this cancellation request. This
   * information can be useful for diagnosing problems by tracing back the chain of events leading
   * up to this event.
   */
  decisionTaskCompletedEventId: number;
  /**
   * The data attached to the event that the decider can use in subsequent workflow tasks. This data
   * isn't sent to the workflow execution.
   */
  control?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const requestCancelExternalWorkflowExecutionFailedEventAttributesSchema: Schema<RequestCancelExternalWorkflowExecutionFailedEventAttributes> =
  s.object<RequestCancelExternalWorkflowExecutionFailedEventAttributes>(
    {
      workflowId: s.string(),
      runId: s.optional(s.string()),
      cause: cause8Schema,
      initiatedEventId: s.int(),
      decisionTaskCompletedEventId: s.int(),
      control: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
